#include "core.hpp"
#include <cctype>
#include <iostream>
#include <stdexcept>

namespace {
void usage(){std::cerr<<"Rescate USB 0.4.0 — diagnóstico de imágenes, solo lectura\nUso: rescateusb <imagen> [--json] [--json-out ARCHIVO] [--expected-sha256 HASH] [--debug]\n     rescateusb --self-test\n";}
}
int main(int argc,char** argv){using namespace rescateusb;try{if(argc==2&&std::string(argv[1])=="--self-test"){run_self_tests();return 0;}if(argc<2){usage();return 2;}std::string path=argv[1],expected,json_output;bool json=false,debug=false;for(int i=2;i<argc;i++){std::string arg=argv[i];if(arg=="--json")json=true;else if(arg=="--debug")debug=true;else if((arg=="--expected-sha256"||arg=="--json-out")&&i+1<argc){std::string value=argv[++i];if(arg=="--expected-sha256")expected=value;else json_output=value;}else{usage();return 2;}}debug_log(debug,"diagnostic started");Report report=analyze_image(path,debug);bool hash_match=true;if(!expected.empty()){for(char& c:expected)c=char(std::tolower(static_cast<unsigned char>(c)));hash_match=expected.size()==64&&expected==report.sha256;}std::string json_text=report_json(path,report,!expected.empty(),hash_match);if(!json_output.empty()){std::ofstream out(json_output,std::ios::binary);if(!out)throw std::runtime_error("Cannot create JSON report");out<<json_text<<'\n';if(!out)throw std::runtime_error("Cannot write JSON report");debug_log(debug,"JSON report written to "+json_output);}if(json)std::cout<<json_text<<'\n';else{std::cout<<"Rescate USB — diagnóstico de solo lectura\nArchivo: "<<path<<"\nTamaño: "<<report.size_bytes<<" bytes\nSHA-256: "<<report.sha256<<"\nTabla: "<<report.format<<"\nParticiones: "<<report.partitions<<"\nResultado: "<<(report.valid?"VÁLIDO":"REVISAR")<<" — "<<report.detail<<'\n';if(!expected.empty())std::cout<<"Hash esperado: "<<(hash_match?"coincide":"NO coincide")<<'\n';}if(!hash_match)return 3;return report.valid?0:1;}catch(const std::exception& error){std::cerr<<"Error: "<<error.what()<<'\n';return 2;}}
